          "variadic": false,
          "mandatory": false,
          "defaultValue": null,
          "descriptionKey": "commands.config.prune.certsOnlyOption",
          "label": "Restrict to the ACME cert-cache bucket. Skips archive purging and cross-reference cleanup. Mutually exclusive with --archives-only and --refs-only."
